// metabeast-remote — Remote MCP Worker scaffold
// ─────────────────────────────────────────────────────────────────────────
// Minimal Streamable-HTTP MCP server: /health for CI + local probes,
// /mcp echoes posted bodies so your client can verify the plumbing works
// before you wire full JSON-RPC 2.0 handling.
//
// This is a starting point. To extend:
//   1. Parse req body as JSON-RPC (method + params + id)
//   2. Dispatch on method:
//      - "initialize"      → return server capabilities
//      - "tools/list"      → return [{ name, description, inputSchema }, …]
//      - "tools/call"      → execute named tool, return {content: [...]}
//      - "ping"            → {}
//   3. Support batched (array) and single JSON-RPC requests
//   4. Gate /mcp behind a bearer token (compare constant-time, not with ===)
// ─────────────────────────────────────────────────────────────────────────

export interface Env {
  AGENT_NAME: string;
  AGENT_CLASS: string;
  FREQUENCY_HZ: string;
  // Add secrets here when you wire auth:
  // MCP_AUTH_TOKEN: string;
}

const CORS_HEADERS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET,POST,OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type, Authorization",
};

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url);

    // CORS preflight
    if (request.method === "OPTIONS") {
      return new Response(null, { status: 204, headers: CORS_HEADERS });
    }

    // Identity card
    if (request.method === "GET" && url.pathname === "/") {
      return Response.json(
        {
          agent: {
            name: env.AGENT_NAME || "metabeast-remote",
            class: env.AGENT_CLASS || "Remote MCP scaffold",
            frequency_hz: Number(env.FREQUENCY_HZ || 396),
          },
          endpoints: ["GET /health", "POST /mcp"],
          notes: [
            "This worker is a Streamable-HTTP MCP scaffold.",
            "Custom hostname attachment is manual — see README.",
          ],
        },
        { headers: CORS_HEADERS },
      );
    }

    // Health — for CI, uptime probes, mc96-follower
    if (request.method === "GET" && url.pathname === "/health") {
      return Response.json(
        {
          ok: true,
          status: "ok",
          agent: env.AGENT_NAME || "metabeast-remote",
          ts: new Date().toISOString(),
          standards_version: "1.0",
        },
        { headers: CORS_HEADERS },
      );
    }

    // Clause 12 — Standards self-attestation
    if (request.method === "GET" && url.pathname === "/standards") {
      return Response.json(
        {
          standards_version: "1.0",
          bot: env.AGENT_NAME || "metabeast-remote",
          clauses: {
            "1_identity": true,
            "2_health": true,
            "3_constant_time_auth": "exempt_scaffold_no_writes",
            "4_consent": "exempt_scaffold_no_writes",
            "5_ledger": "exempt_scaffold_no_writes",
            "6_disposability": true,
            "7_observability": true,
            "8_secrets": true,
            "9_compatibility": true,
            "10_kill_switch": "n/a",
            "11_critical_escalation": "exempt_scaffold_no_writes",
            "12_standards_self_attestation": true,
          },
          audited_at: new Date().toISOString(),
        },
        { headers: CORS_HEADERS },
      );
    }

    // MCP endpoint — echoes the body so clients can verify transport
    // before full JSON-RPC handling is wired.
    if (request.method === "POST" && url.pathname === "/mcp") {
      const ctype = (request.headers.get("content-type") || "").toLowerCase();
      let echo: unknown;
      try {
        if (ctype.includes("application/json")) {
          echo = await request.json();
        } else {
          echo = await request.text();
        }
      } catch {
        echo = null;
      }
      return Response.json(
        { received: true, echo, ts: new Date().toISOString() },
        { headers: CORS_HEADERS },
      );
    }

    return new Response("metabeast-remote — GET /, GET /health, POST /mcp (echo)\n", {
      status: 404,
      headers: { ...CORS_HEADERS, "Content-Type": "text/plain" },
    });
  },
};
